package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
public class DefenseBlock extends BaseEntityBlock{
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final IntegerProperty PART=IntegerProperty.create("part",0,255);public static final ThreadLocal<Boolean>MUTATING=ThreadLocal.withInitial(()->false);public final int kind;
 public DefenseBlock(Properties p,int kind){super(p);this.kind=kind;registerDefaultState(stateDefinition.any().setValue(FACING,Direction.SOUTH).setValue(PART,0));}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING,PART);}public static BlockPos root(BlockPos p,BlockState s){var b=(DefenseBlock)s.getBlock();int part=s.getValue(PART);return part<DefenseGeometry.MODELS[b.kind].cells.length?DefenseGeometry.MODELS[b.kind].root(p,s.getValue(FACING),part):p;}
 public static DefenseBlockEntity main(Level l,BlockPos p,BlockState s){var r=root(p,s);return l.hasChunkAt(r)&&l.getBlockEntity(r)instanceof DefenseBlockEntity b?b:null;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,DefenseItem.face(c.getPlayer(),c.getItemInHand()));}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,LivingEntity placer,ItemStack item){if(l.getBlockEntity(p)instanceof DefenseBlockEntity b){var tag=DefenseItem.data(item);if(tag.contains("Installation")){b.restoreTag(tag.getCompound("Installation"));b.nextShot=l.getGameTime()+Math.max(0,Math.min(1200,tag.getCompound("Installation").getInt("Cooldown")));}b.id=java.util.UUID.randomUUID();if(b.owner==null&&placer!=null){b.owner=placer.getUUID();b.ownerName=placer.getScoreboardName();}if(l instanceof net.minecraft.server.level.ServerLevel server)DefenseData.get(server).register(new DefenseData.Site(b.id,kind,p,s.getValue(FACING),b.owner,b.ownerName));b.changed();}}
 @Override public InteractionResult use(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){return interact(s,l,p,player,hand,hit);}
 public InteractionResult interact(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){if(player.getItemInHand(hand).getItem()instanceof DefenseItem||player.getItemInHand(hand).getItem()instanceof DefenseLinkTool)return InteractionResult.PASS;var b=main(l,p,s);if(b==null)return InteractionResult.FAIL;if(player.isShiftKeyDown()&&player.getItemInHand(hand).is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){if(player instanceof net.minecraft.server.level.ServerPlayer server&&!b.remove(server,true))server.displayClientMessage(net.minecraft.network.chat.Component.translatable("defense.pack_denied"),true);return InteractionResult.sidedSuccess(l.isClientSide);}
  var panel=b.geometry().worldBox(b.getBlockPos(),b.facing(),b.geometry().panel).inflate(.45);if(!panel.contains(hit.getLocation())){player.displayClientMessage(net.minecraft.network.chat.Component.translatable("defense.use_panel"),true);return InteractionResult.SUCCESS;}if(l.isClientSide){DefenseClient.open(b);return InteractionResult.SUCCESS;}if(player instanceof net.minecraft.server.level.ServerPlayer server){if(!b.canOperate(server))return InteractionResult.FAIL;b.control(server,0,0,new java.util.UUID(0,0));return InteractionResult.CONSUME;}return InteractionResult.FAIL;}
 public static BlockHitResult clipOutside(DefenseBlockEntity source,Vec3 a,Vec3 b){return source.getLevel().clip(new ClipContext(a,b,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,(Entity)null){@Override public VoxelShape getBlockShape(BlockState s,BlockGetter l,BlockPos p){if(s.getBlock()instanceof DefenseBlock block&&block.kind==source.kind()&&DefenseBlock.root(p,s).equals(source.getBlockPos()))return Shapes.empty();return super.getBlockShape(s,l,p);}});}
 @Override public VoxelShape getShape(BlockState s,BlockGetter getter,BlockPos p,CollisionContext c){var geo=DefenseGeometry.MODELS[kind];int part=s.getValue(PART);if(part>=geo.cells.length)return Shapes.empty();var b=getter instanceof Level l?main(l,p,s):null;return geo.collision(s.getValue(FACING),part,b==null?12:Math.round(b.pose(0)*12));}
 @Override public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){if(c instanceof EntityCollisionContext context&&context.getEntity()instanceof Pm01Entity missile&&missile.ignoresInstallation(root(p,s)))return Shapes.empty();return getShape(s,l,p,c);}
 @Override public RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}@Override public VoxelShape getOcclusionShape(BlockState s,BlockGetter l,BlockPos p){return Shapes.empty();}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return s.getValue(PART)==0?new DefenseBlockEntity(p,s):null;}@Override public <T extends BlockEntity>BlockEntityTicker<T>getTicker(Level l,BlockState s,BlockEntityType<T>type){return !l.isClientSide&&s.getValue(PART)==0?createTickerHelper(type,AddonBlockEntities.DEFENSE.get(),DefenseBlockEntity::tick):null;}
 @Override public void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(!l.isClientSide&&!MUTATING.get()&&!s.is(next.getBlock())){var b=main(l,p,s);if(b!=null)b.remove(null,l.restoringBlockSnapshots);else if(l instanceof net.minecraft.server.level.ServerLevel server)DefenseData.get(server).removeAt(server,root(p,s),kind);}super.onRemove(s,l,p,next,moving);}
 @Override public void neighborChanged(BlockState s,Level l,BlockPos p,Block changed,BlockPos at,boolean moving){if(l.isClientSide||MUTATING.get())return;var geo=DefenseGeometry.MODELS[kind];int part=s.getValue(PART);if(part<geo.cells.length&&geo.cells[part][1]==0&&at.equals(p.below())&&!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP)){var b=main(l,p,s);if(b!=null)b.remove(null,l.restoringBlockSnapshots);else if(l instanceof net.minecraft.server.level.ServerLevel server)DefenseData.get(server).removeAt(server,root(p,s),kind);}}
 @Override public BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}@Override public BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
}
